import {newProject,uid,now,snapshot,sha256} from './core.js';
export async function sampleProject(){
 const p=newProject('Field gateway · bench assessment','Field gateway / FG-01','DEMONSTRATION ONLY. Fictional gateway on an isolated test network. Device hardware, serial console, vendor firmware and local services are in scope. Cloud services and third-party systems are excluded.');
 p.sample=true;const d=p.devices[0];Object.assign(d,{model:'FG-100 · laboratory reference',hw:'Rev. C',firmware:'1.4.2',notes:'Fictional sample device. Measurements and results illustrate a workflow; they are not a real product assessment.'});
 const addEvidence=async(title,kind,text,source)=>{const bytes=new TextEncoder().encode(text);const e={id:uid('ev'),deviceId:d.id,title,kind,mime:'text/plain',data:'data:text/plain;base64,'+btoa(text),hash:await sha256(bytes),size:bytes.length,createdAt:now(),source,tool:'PROBE sample fixture',conditions:'Fictional laboratory sample; no hardware connected.',notes:''};p.evidence.push(e);return e.id;};
 const boot='[0.000] FG-100 bootloader 1.2\n[0.218] Board revision C; firmware 1.4.2\n[0.810] Storage initialized\n[1.306] Network interface up\n[1.724] Diagnostic service listening on 8080\n[2.084] Console ready: login required\n[2.190] Application ready';
 const be=await addEvidence('Startup capture · firmware 1.4.2','Serial log',boot,'Demo serial adapter / 115200 baud');
 p.sessions.push({id:uid('session'),deviceId:d.id,label:'Cold start · 1.4.2',createdAt:now(),evidenceId:be,lines:boot.split('\n').map((text,i)=>({t:new Date(Date.now()-20000+i*400).toISOString(),dir:'RX',text,hex:[...new TextEncoder().encode(text+'\n')].map(b=>b.toString(16).padStart(2,'0')).join(' ')})),events:[{t:now(),text:'Application ready'}]});
 const ie=[['Console header','UART','Verified',25,70,'GND · TX · RX','3.3 V'],['Debug pads','SWD','Suspected',73,33,'Unverified','Unmeasured'],['External flash','SPI','Observed',61,68,'SOIC-8 package','Unmeasured'],['Ethernet','Ethernet','Verified',15,38,'RJ45','N/A'],['Radio module','Wi-Fi','Observed',79,73,'On-board module','N/A']];
 p.interfaces=ie.map(([label,type,status,x,y,pins,voltage])=>({id:uid('if'),deviceId:d.id,label,type,status,x,y,pins,voltage,notes:type==='UART'?'Authentication prompt observed after startup. Pinout and voltage are fictional sample values.':'Evidence required before drawing a security conclusion.',evidenceIds:type==='UART'?[be]:[]}));
 p.connections.push({id:uid('link'),deviceId:d.id,from:'FG-01',to:'Local management workstation',protocol:'HTTPS / TCP 443',boundary:'Device → management LAN',notes:'In-scope local management interface.'});
 const scan='<?xml version="1.0"?><nmaprun scanner="nmap" version="sample"><host><status state="up"/><address addr="192.0.2.24" addrtype="ipv4"/><ports><port protocol="tcp" portid="443"><state state="open"/><service name="https" product="FG management" version="1.4.2"/></port><port protocol="tcp" portid="8080"><state state="open"/><service name="http" product="Diagnostic endpoint"/></port></ports></host></nmaprun>';
 const ne=await addEvidence('Network inventory · isolated bench','Network scan',scan,'Fictional Nmap XML fixture; 192.0.2.0/24 documentation network');
 p.services=[{id:uid('svc'),deviceId:d.id,host:'192.0.2.24',port:443,protocol:'tcp',state:'open',name:'https',version:'FG management 1.4.2',evidenceId:ne},{id:uid('svc'),deviceId:d.id,host:'192.0.2.24',port:8080,protocol:'tcp',state:'open',name:'http',version:'Diagnostic endpoint',evidenceId:ne}];
 p.findings=[{id:uid('finding'),deviceId:d.id,title:'Diagnostic service remains exposed after provisioning',severity:'Medium',confidence:'High',status:'Open',component:'Ethernet / TCP 8080',observation:'The fictional startup log announces a diagnostic listener and the sample scan records TCP 8080 open after provisioning.',impact:'Potentially unnecessary access to diagnostic behavior on the management network. The capabilities and authentication of this endpoint still require validation.',reproduction:'With the fictional device in its provisioned state, capture startup output and import a service inventory from the management LAN.',remediation:'Review whether the diagnostic service is needed in production. Disable it or constrain and authenticate access as appropriate.',retest:'Repeat startup capture and service inventory after the firmware change; validate the resulting access policy.',evidenceIds:[be,ne],createdAt:now()}];
 p.tests=[{id:uid('test'),deviceId:d.id,testId:'scope',status:'Passed',notes:'Demonstration scope recorded.',evidenceIds:[]},{id:uid('test'),deviceId:d.id,testId:'boot',status:'Passed',notes:'No sensitive values in the supplied sample excerpt; this is not a complete real-device test.',evidenceIds:[be]},{id:uid('test'),deviceId:d.id,testId:'services',status:'Failed',notes:'Sample diagnostic service remains exposed.',evidenceIds:[ne]}];
 p.assumptions=[{id:uid('assumption'),deviceId:d.id,text:'The diagnostic endpoint is not intended for routine production use.',status:'Unverified',basis:'Requires product-owner confirmation.'}];
 p.baselines.push({id:uid('base'),deviceId:d.id,label:'Initial assessment · firmware 1.4.2',createdAt:now(),conditions:'Fictional production configuration; management-LAN vantage point.',snapshot:snapshot(p)});
 return p;
}
